create table if not exists atom_board (
  key text primary key,
  data jsonb,
  updated_at timestamptz not null default now()
);
create index if not exists atom_board_updated on atom_board (updated_at);
create table if not exists gmail_tokens (
  email text primary key,
  name text,
  refresh_token text not null,
  updated_at timestamptz default now()
);
create table if not exists atom_mail (
  id bigserial primary key,
  to_email text not null, to_name text, subject text, body text,
  created_at timestamptz default now()
);

